import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import "./Emergency.css";

const Emergency = () => {
  const navigate = useNavigate();
  const [contacts, setContacts] = useState([]);
  const [loading, setLoading] = useState(true);

  /* ========================
     FETCH CONTACTS
  ======================== */
  useEffect(() => {
    axios
      .get("http://localhost:5001/api/contacts")
      .then((res) => {
        setContacts(res.data);
        setLoading(false);
      })
      .catch((err) => {
        console.error("Error fetching contacts:", err);
        setLoading(false);
      });
  }, []);

  /* ========================
     HANDLE CALL
  ======================== */
  const handleCall = async (contact) => {
    if (!navigator.geolocation) {
      await saveCall(contact, null, null);
      window.location.href = `tel:${contact.number}`;
      return;
    }

    navigator.geolocation.getCurrentPosition(
      async (position) => {
        const latitude = position.coords.latitude;
        const longitude = position.coords.longitude;

        await saveCall(contact, latitude, longitude);
        window.location.href = `tel:${contact.number}`;
      },
      async (error) => {
        console.warn("Location denied:", error.message);

        // Save call even if location denied
        await saveCall(contact, null, null);
        window.location.href = `tel:${contact.number}`;
      },
      {
        enableHighAccuracy: true,
        timeout: 10000,
        maximumAge: 0,
      }
    );
  };

  /* ========================
     SAVE CALL TO BACKEND
  ======================== */
  const saveCall = async (contact, latitude, longitude) => {
    try {
      await axios.post("http://localhost:5001/api/emergency-calls", {
        contactName: contact.name,
        phoneNumber: contact.number,
        latitude,
        longitude,
      });

      console.log("✅ Emergency call saved with location");
    } catch (error) {
      console.error("❌ Failed to save emergency call:", error);
    }
  };

  return (
    <div className="emergency-container">
      <h1>🚨 Emergency Contacts</h1>

      {loading ? (
        <p className="loading-text">Fetching emergency contacts...</p>
      ) : (
        <div className="contact-grid">
          {contacts.map((contact) => (
            <div key={contact._id} className="contact-card">
              <h3>{contact.name}</h3>
              <p>{contact.number}</p>

              <button
                className="call-btn"
                onClick={() => handleCall(contact)}
              >
                📞 Call Now
              </button>
            </div>
          ))}
        </div>
      )}

      <button className="back-btn" onClick={() => navigate("/")}>
        ⬅ Back to Home
      </button>
    </div>
  );
};

export default Emergency;
